'use strict';

const http = require('http');
const fs = require('fs');
const fsp = fs.promises;
const path = require('path');
const crypto = require('crypto');

function readBody(req) {
  return new Promise((resolve, reject) => {
    const chunks = [];
    req.on('data', (chunk) => chunks.push(chunk));
    req.on('end', () => resolve(Buffer.concat(chunks)));
    req.on('error', reject);
  });
}

async function handlePutBlob(config, key, req, res) {
  const body = await readBody(req);
  const sha256 = crypto.createHash('sha256').update(body).digest('hex');
  const filePath = path.join(config.dataDir, key);

  await fsp.mkdir(path.dirname(filePath), { recursive: true });
  await fsp.writeFile(filePath, body);

  res.writeHead(201, { 'Content-Type': 'application/json' });
  res.end(JSON.stringify({ key, sha256, size: body.length }));
}

async function handleGetBlob(config, key, req, res) {
  const filePath = path.join(config.dataDir, key);

  let body;
  try {
    body = await fsp.readFile(filePath);
  } catch (err) {
    if (err.code === 'ENOENT') {
      res.writeHead(404, { 'Content-Type': 'text/plain' });
      res.end('not found');
      return;
    }
    throw err;
  }

  res.writeHead(200, { 'Content-Type': 'application/octet-stream' });
  res.end(body);
}

function createServer(config) {
  return http.createServer((req, res) => {
    const pathname = new URL(req.url, 'http://localhost').pathname;

    if (req.method === 'GET' && pathname === '/healthz') {
      res.writeHead(200, { 'Content-Type': 'text/plain' });
      res.end('ok');
      return;
    }

    const blobMatch = pathname.match(/^\/blobs\/(.+)$/);
    if (blobMatch) {
      const key = decodeURIComponent(blobMatch[1]);

      const handler = req.method === 'PUT' ? handlePutBlob
        : req.method === 'GET' ? handleGetBlob
        : null;

      if (handler) {
        Promise.resolve(handler(config, key, req, res)).catch((err) => {
          res.writeHead(500, { 'Content-Type': 'text/plain' });
          res.end(`internal error: ${err.message}`);
        });
        return;
      }
    }

    res.writeHead(404, { 'Content-Type': 'text/plain' });
    res.end('not found');
  });
}

module.exports = { createServer };

'use strict';

const test = require('node:test');
const assert = require('node:assert/strict');
const { resolveConfig } = require('../src/config');

test('reads --data-dir and --port from argv', () => {
  const config = resolveConfig(['--data-dir', '/tmp/data', '--port', '9090'], {});
  assert.deepEqual(config, { dataDir: '/tmp/data', port: 9090 });
});

test('defaults port to 8080 when not given', () => {
  const config = resolveConfig(['--data-dir', '/tmp/data'], {});
  assert.equal(config.port, 8080);
});

test('falls back to SYNCBOX_DATA_DIR and SYNCBOX_PORT env vars', () => {
  const config = resolveConfig([], { SYNCBOX_DATA_DIR: '/tmp/env-data', SYNCBOX_PORT: '9999' });
  assert.deepEqual(config, { dataDir: '/tmp/env-data', port: 9999 });
});

test('argv flags take precedence over env vars', () => {
  const config = resolveConfig(
    ['--data-dir', '/tmp/argv-data', '--port', '7070'],
    { SYNCBOX_DATA_DIR: '/tmp/env-data', SYNCBOX_PORT: '9999' }
  );
  assert.deepEqual(config, { dataDir: '/tmp/argv-data', port: 7070 });
});

test('throws when --data-dir is missing everywhere', () => {
  assert.throws(() => resolveConfig([], {}), /--data-dir is required/);
});

test('throws on a non-numeric port', () => {
  assert.throws(() => resolveConfig(['--data-dir', '/tmp/data', '--port', 'abc'], {}), /invalid port/);
});

test('throws on an unknown argument', () => {
  assert.throws(() => resolveConfig(['--bogus', 'x'], {}), /unknown argument/);
});

'use strict';

const test = require('node:test');
const assert = require('node:assert/strict');
const http = require('node:http');
const fs = require('node:fs');
const os = require('node:os');
const path = require('node:path');
const crypto = require('node:crypto');
const { createServer } = require('../src/server');

function listen(server) {
  return new Promise((resolve) => {
    server.listen(0, '127.0.0.1', () => resolve(server.address().port));
  });
}

function get(port, path) {
  return new Promise((resolve, reject) => {
    http.get({ host: '127.0.0.1', port, path }, (res) => {
      const chunks = [];
      res.on('data', (chunk) => chunks.push(chunk));
      res.on('end', () => resolve({ status: res.statusCode, body: Buffer.concat(chunks) }));
    }).on('error', reject);
  });
}

function request(port, method, path, body) {
  return new Promise((resolve, reject) => {
    const req = http.request({ host: '127.0.0.1', port, path, method }, (res) => {
      const chunks = [];
      res.on('data', (chunk) => chunks.push(chunk));
      res.on('end', () => resolve({ status: res.statusCode, body: Buffer.concat(chunks) }));
    });
    req.on('error', reject);
    if (body !== undefined) req.write(body);
    req.end();
  });
}

function tempDataDir() {
  return fs.mkdtempSync(path.join(os.tmpdir(), 'syncbox-test-'));
}

test('GET /healthz returns 200', async (t) => {
  const server = createServer({ dataDir: '/tmp/unused' });
  const port = await listen(server);
  t.after(() => server.close());

  const res = await get(port, '/healthz');
  assert.equal(res.status, 200);
});

test('unknown route returns 404', async (t) => {
  const server = createServer({ dataDir: '/tmp/unused' });
  const port = await listen(server);
  t.after(() => server.close());

  const res = await get(port, '/nope');
  assert.equal(res.status, 404);
});

test('PUT /blobs/{key} stores the blob and returns key/sha256/size', async (t) => {
  const dataDir = tempDataDir();
  const server = createServer({ dataDir });
  const port = await listen(server);
  t.after(() => server.close());

  const content = Buffer.from('hello world');
  const res = await request(port, 'PUT', '/blobs/greeting.txt', content);

  assert.equal(res.status, 201);
  const parsed = JSON.parse(res.body.toString());
  assert.deepEqual(parsed, {
    key: 'greeting.txt',
    sha256: crypto.createHash('sha256').update(content).digest('hex'),
    size: content.length,
  });
  assert.deepEqual(fs.readFileSync(path.join(dataDir, 'greeting.txt')), content);
});

test('PUT /blobs/{key} creates nested directories as needed', async (t) => {
  const dataDir = tempDataDir();
  const server = createServer({ dataDir });
  const port = await listen(server);
  t.after(() => server.close());

  const content = Buffer.from('# readme');
  const res = await request(port, 'PUT', '/blobs/docs/readme.txt', content);

  assert.equal(res.status, 201);
  assert.deepEqual(fs.readFileSync(path.join(dataDir, 'docs', 'readme.txt')), content);
});

test('PUT /blobs/{key} overwrites an existing blob', async (t) => {
  const dataDir = tempDataDir();
  const server = createServer({ dataDir });
  const port = await listen(server);
  t.after(() => server.close());

  await request(port, 'PUT', '/blobs/a.txt', Buffer.from('first'));
  const second = Buffer.from('second, longer content');
  const res = await request(port, 'PUT', '/blobs/a.txt', second);

  assert.equal(res.status, 201);
  assert.deepEqual(fs.readFileSync(path.join(dataDir, 'a.txt')), second);
});

test('GET /blobs/{key} returns the stored bytes', async (t) => {
  const dataDir = tempDataDir();
  const server = createServer({ dataDir });
  const port = await listen(server);
  t.after(() => server.close());

  const content = Buffer.from([0, 1, 2, 255, 254]);
  await request(port, 'PUT', '/blobs/binary.dat', content);

  const res = await get(port, '/blobs/binary.dat');
  assert.equal(res.status, 200);
  assert.deepEqual(res.body, content);
});

test('GET /blobs/{key} for a nested key returns the stored bytes', async (t) => {
  const dataDir = tempDataDir();
  const server = createServer({ dataDir });
  const port = await listen(server);
  t.after(() => server.close());

  const content = Buffer.from('nested content');
  await request(port, 'PUT', '/blobs/docs/readme.txt', content);

  const res = await get(port, '/blobs/docs/readme.txt');
  assert.equal(res.status, 200);
  assert.deepEqual(res.body, content);
});

test('GET /blobs/{key} returns 404 when the blob does not exist', async (t) => {
  const dataDir = tempDataDir();
  const server = createServer({ dataDir });
  const port = await listen(server);
  t.after(() => server.close());

  const res = await get(port, '/blobs/missing.txt');
  assert.equal(res.status, 404);
});
